<?php
require_once __DIR__.'/../servisi/Sesija.php';Sesija::zahtevajPrijavu();require_once __DIR__.'/../podaci/IznajmljivanjeRepozitorijum.php';require_once __DIR__.'/../podaci/VoziloRepozitorijum.php';require_once __DIR__.'/../validacija/Validacija.php';
$id=(int)($_GET['id']??$_POST['id']??0);$repo=new IznajmljivanjeRepozitorijum();$r=$repo->dajPoId($id);if(!$r)die('Iznajmljivanje nije pronađeno.');$greska='';
$vRepo=new VoziloRepozitorijum();$vozila=$vRepo->dajSlobodna();foreach($r['Stavke'] as $s){$postoji=false;foreach($vozila as $v)if($v['ID']==$s['VoziloID'])$postoji=true;if(!$postoji){$v=$vRepo->dajPoId((int)$s['VoziloID']);if($v)$vozila[]=$v;}}
if($_SERVER['REQUEST_METHOD']==='POST'){$od=$_POST['datumOd']??'';$do=$_POST['datumDo']??'';$iz=$_POST['vozila']??[];$greska=Validacija::datumOpseg($od,$do)??'';if(!$greska&&!$iz)$greska='Izaberite najmanje jedno vozilo.';if(!$greska){try{$repo->izmeni($id,$od,$do,$iz);Sesija::postaviPoruku('Izmene su uspešno sačuvane.');header('Location: detalji.php?id='.$id);exit;}catch(Throwable $e){$greska=$e->getMessage();}}}
$izabrani=array_column($r['Stavke'],'VoziloID');
?>
<!doctype html><html lang="sr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Izmena | Rent-a-Car</title><link rel="stylesheet" href="../javno/css/stil.css"><script src="../javno/js/validacija.js"></script></head><body><header class="zaglavlje"><strong>Rent-a-Car</strong><nav><a href="index.php">Nazad na pregled</a><a href="../prijava/odjava.php">Odjava</a></nav></header><main class="kontejner"><h1>Izmena iznajmljivanja #<?=$id?></h1><p class="podnaslov">Promenite period ili vozila vezana za ovo iznajmljivanje.</p><?php if($greska):?><div class="greska"><?=htmlspecialchars($greska)?></div><?php endif;?><form method="post" onsubmit="return proveriIznajmljivanje(this)"><input type="hidden" name="id" value="<?=$id?>"><div class="forma-red"><div class="forma-polje"><label>Datum od</label><input type="date" name="datumOd" required value="<?=$r['DatumOd']?>"></div><div class="forma-polje"><label>Datum do</label><input type="date" name="datumDo" required value="<?=$r['DatumDo']?>"></div></div><h2>Izabrana vozila</h2><div class="stavke-lista"><?php foreach($vozila as $v):?><label class="stavka"><input type="checkbox" name="vozila[]" value="<?=$v['ID']?>" <?=in_array($v['ID'],$izabrani)?'checked':''?>><span><strong><?=htmlspecialchars($v['Marka'].' '.$v['Model'])?></strong> · <?=htmlspecialchars($v['Registracija'])?></span></label><?php endforeach;?></div><div class="traka-akcija"><button>Sačuvaj izmene</button><a class="dugme dugme-sekundarno" href="detalji.php?id=<?=$id?>">Odustani</a></div></form></main></body></html>